def initialize
  @step_chances       = {}
  @encounter_tables   = {}
  @chance_accumulator = 0
end

def setup(map_ID)
  @step_count       = 0
  @step_chances     = {}
  @encounter_tables = {}
  encounter_data = GameData::Encounter.get(map_ID, $PokemonGlobal.encounter_version)
  if encounter_data
    encounter_data.step_chances.each { |type, value| @step_chances[type] = value }
    @encounter_tables = Marshal.load(Marshal.dump(encounter_data.types))
  end
end

def pbInitialize(pkmn, idxParty, batonPass = false)
  pbInitPokemon(pkmn, idxParty)
  pbInitEffects(batonPass)
  @damageState.reset
end

def pbInitPokemon(pkmn, idxParty)
  raise _INTL("An egg can't be an active Pokémon.") if pkmn.egg?
  @name         = pkmn.name
  @species      = pkmn.species
  @form         = pkmn.form
  @level        = pkmn.level
  @hp           = pkmn.hp
  @totalhp      = pkmn.totalhp
  @types        = pkmn.types
  @ability_id   = pkmn.ability_id
  @item_id      = pkmn.item_id
  @attack       = pkmn.attack
  @defense      = pkmn.defense
  @spatk        = pkmn.spatk
  @spdef        = pkmn.spdef
  @speed        = pkmn.speed
  @status       = pkmn.status
  @statusCount  = pkmn.statusCount
  @pokemon      = pkmn
  @pokemonIndex = idxParty
  @participants = []   # Participants earn Exp. if this battler is defeated
  @moves        = []
  pkmn.moves.each_with_index do |m, i|
    @moves[i] = Battle::Move.from_pokemon_move(@battle, m)
  end
end

